function toBase64(buffer: ArrayBuffer): string { let binary = ""; for (const byte of new Uint8Array(buffer)) binary += String.fromCharCode(byte); return btoa(binary); }
function readTelegramLanguageCode(initData: string): string | undefined { try { const value = new URLSearchParams(initData).get("user"); if (!value) return undefined; return (JSON.parse(value) as { language_code?: string }).language_code; } catch { return undefined; } }
