  useEffect(() => { if (import.meta.env.DEV && !isTelegramRuntime && bootStatus === "offline") setVerification({ status: "APPROVED" }); }, [bootStatus, isTelegramRuntime]);
  useEffect(() => { const visible = isTelegramRuntime && (onboarded ? !topLevelScreen : setupStep !== "device"); const onBack = () => { if (!onboarded) { if (setupStep === "pin") setSetupStep("referrer"); else if (setupStep === "referrer") setSetupStep("device"); return; } const next = screen === "chat-room" ? "chat" : "hall"; setScreen(next); window.history.pushState({}, "", pathForScreen(next)); }; return configureTelegramBackButton({ visible, onClick: onBack }); }, [isTelegramRuntime, onboarded, setupStep, topLevelScreen, screen]);
  useEffect(() => { const source = typeof EventSource === "undefined" ? undefined : new EventSource(`${apiUrl}/api/rounds/${initialState.round.id}/realtime`, { withCredentials: true }); if (!source) return undefined; const onRoundEvent = (event: MessageEvent<string>) => { try { const payload = JSON.parse(event.data) as { to?: DemoState["round"]["state"] }; if (payload.to) setState((current) => ({ ...current, round: { ...current.round, state: payload.to as DemoState["round"]["state"] } })); } catch { /* keep last snapshot */ } }; source.addEventListener("round", onRoundEvent); source.onerror = () => source.close(); return () => { source.removeEventListener("round", onRoundEvent); source.close(); }; }, [apiUrl]);
