  const move = (next: Screen) => { hapticSelection(); setToast(""); if ((next === "wallet" || next === "chat" || next === "chat-room") && verification.status !== "APPROVED") { setVerificationOpen(true); return; } setScreen(next); window.history.pushState({}, "", pathForScreen(next)); window.scrollTo({ top: 0, behavior: "auto" }); };
