  const submitVerification = async (legalName: string, tngAccountNo: string) => { const normalized = tngAccountNo.replace(/[\s-]/g, ""); if (legalName.trim().length < 2 || !/^\d{8,20}$/.test(normalized)) throw new Error("请填写真实姓名和有效的 TNG eWallet 账号"); const response = await writeOrFallback("/api/verification/submit", `ui-verification-${Date.now()}`, { legalName: legalName.trim(), tngAccountNo: normalized }, "实名认证提交失败，请重试"); let next: Verification = { status: "PENDING", submittedAt: new Date().toISOString(), tngAccountLast4: `••••${normalized.slice(-4)}` }; if (response?.ok) { try { const payload = await response.json() as { result?: Verification }; next = payload.result ?? next; } catch { /* keep masked local status */ } } setVerification(next); setVerificationOpen(true); notify("实名认证已提交，等待审核", "success"); };
